CELL_FINGER_INSERTION_DEPTH_M = 0.035
CELL_GAP_ALIGNMENT_TOLERANCE_M = 0.022
CELL_GAP_ALIGNMENT_TIMEOUT_ACCEPTANCE_M = 0.025
